class Media(SyncResource):
    """Media operations."""

    def list_media(
        self,
        *,
        purpose: Optional[_m.MediaPurposeKnown] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> Page[_m.Media]:
        """List media in the workspace

        Lists media items uploaded or imported through v3, newest first. Media uploaded in the web app is not
        addressable.

        Args:
            purpose: Only this purpose.
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
        """
        return self._list(
            _ops.listMedia,
            _m.MediaList,
            query={"purpose": purpose, "limit": limit, "cursor": cursor},
            options=options,
        )

    def import_media(
        self,
        *,
        url: str,
        filename: Optional[str] = None,
        purpose: Optional[_m.MediaPurposeKnown] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Import media from a public URL

        Starts a `media_import` job that imports a file from a public http(s) URL as a media item and whose result
        carries `media_id`. URLs are checked against private addresses (no IP literals, credentials, `s3://` or
        non-standard ports). Until generic imports open, only YouTube, Google Drive, Vimeo and allow-listed hosts are
        accepted. Voice samples (`purpose: voice_sample`) may be audio or video (its audio is extracted to MP3); a
        sample above the voice-sample limits fails the job with `media_too_large`.

        Args:
            url: Public http(s) URL on port 80/443 (YouTube, Google Drive, Vimeo or an allow-listed host until generic
            imports open). No IP literals or credentials.
            filename: File name to record.
            purpose: Media purpose.
        """
        return self._call(
            _ops.importMedia,
            _m.Job,
            body={"url": url, "filename": filename, "purpose": purpose},
            idempotency_key=idempotency_key,
            options=options,
        )

    def get_media(
        self,
        media_id: str,
        **options: Unpack[RequestOptions],
    ) -> _m.Media:
        """Get a media item

        Returns a media item with its kind, duration and stream metadata. An item exists once its `media_import` job
        has succeeded; a failed import is on the job's `error`.
        """
        return self._call(
            _ops.getMedia,
            _m.Media,
            path={"media_id": media_id},
            options=options,
        )

    def delete_media(
        self,
        media_id: str,
        **options: Unpack[RequestOptions],
    ) -> NoContent:
        """Delete a media item

        Deletes a media item. Projects keep their own copy, so deleting media used by finished projects is safe.
        """
        return self._call(
            _ops.deleteMedia,
            NoContent,
            path={"media_id": media_id},
            options=options,
        )


class Dubbing(SyncResource):
    """Dubbing operations."""

    def create_dub(
        self,
        project_id: str,
        *,
        expected_cost_minutes: int,
        mode: Optional[_m.DubModeKnown] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Dub or redub a project

        Starts a `dub` job: `full` re-voices every segment, `changed_segments` only outdated and not-dubbed ones,
        `auto` (default) picks full without a previous dub or when a full voiceover is needed. Text is voiced as
        written. A `changed_segments` dub merges unchanged clips from generateSegments without voicing or charging
        them again (estimateDub); if all changed segments have one, the shortest is voiced again at its speech price
        (minimum 1 minute). A first or full dub voices every segment. The video and outputs are rebuilt and a
        `dub_completed` version is recorded; segments edited during the dub stay `outdated`.

        Args:
            mode: Dub mode.
            expected_cost_minutes: Cap on the minutes this request may spend (any minute pool). Send the estimate's
            total_minutes. A higher current price fails with 409 cost_changed and spends...
        """
        return self._call(
            _ops.createDub,
            _m.Job,
            path={"project_id": project_id},
            body={"mode": mode, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )

    def estimate_dub(
        self,
        project_id: str,
        *,
        mode: Optional[_m.DubModeKnown] = None,
        expected_cost_minutes: Optional[int] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Estimate:
        """Estimate a dub or redub

        Runs every check of createDub without writing and returns an Estimate: the mode the server would apply, the
        segments to voice and the reused clips, voiced speech, price, engine, `text_adaptation`, eligibility with
        reasons and `balance_after`. If all changed segments have a current clip from generateSegments,
        `assembly_anchor_segment_id` names the shortest, voiced again at its speech price (minimum 1 minute; notice
        `assembly_anchor_voiced`).

        Args:
            mode: Dub mode.
            expected_cost_minutes: Accepted and ignored, so the action's body can be sent unchanged.
        """
        return self._call(
            _ops.estimateDub,
            _m.Estimate,
            path={"project_id": project_id},
            body={"mode": mode, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )

    def create_localization(
        self,
        project_id: str,
        *,
        expected_cost_minutes: int,
        dub: Optional[_p.LocalizationDubInputParam] = None,
        lipsync: Optional[_p.LocalizationLipsyncInputParam] = None,
        onscreen: Optional[_p.LocalizationOnscreenInputParam] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Run dub, lip-sync and on-screen as one job

        Starts one `localization` job: dub (as in createDub), lip-sync, then on-screen, each on the previous result
        and a child job (`stages`); `result.final_output` is the final video. Order `lipsync`, `onscreen` or both. A
        stage with a current result is reused at no charge (`stages[].reused`): a dub with nothing to voice, a paid
        lip-sync of the same model (another model answers 409 `lipsync_already_done`), an on-screen run over the same
        source. A dub that runs re-runs the later stages.

        Args:
            dub: The dub stage; omit for mode `auto`.
            lipsync: Run lip-sync after the dub.
            onscreen: Translate on-screen text last, over the lip-synced video when lip-sync is ordered.
            expected_cost_minutes: Cap on the minutes the whole run may spend (the single total). Send the estimate's
            total_minutes. A higher current price fails with 409 cost_changed and spen...
        """
        return self._call(
            _ops.createLocalization,
            _m.Job,
            path={"project_id": project_id},
            body={"dub": dub, "lipsync": lipsync, "onscreen": onscreen, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )

    def estimate_localization(
        self,
        project_id: str,
        *,
        dub: Optional[_p.LocalizationDubInputParam] = None,
        lipsync: Optional[_p.LocalizationLipsyncInputParam] = None,
        onscreen: Optional[_p.LocalizationOnscreenInputParam] = None,
        resume_job_id: Optional[str] = None,
        expected_cost_minutes: Optional[int] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Estimate:
        """Estimate a dub, lip-sync and on-screen run

        Runs every check of createLocalization without writing and returns an Estimate: one cost line per stage at
        today's price, the single `total_minutes`, the details of the dub stage, eligibility with reasons and
        `balance_after`. With `resume_job_id` it prices resuming that failed run: stages that succeeded cost 0. When
        the plan would trim the lip-sync and on-screen is also ordered, `eligible` is false with the reason
        `localization_combination_not_supported`. A stage with a current result costs 0 (`not_run_reason`): a dub with
        nothing to voice, a paid lip-sync of the same model (a free run does not count), an on-screen run over the
        same source. A dub that runs makes the later stages run and cost too. `details.dub.assembly_anchor_segment_id`
        names the segment voiced again when all changed segments have a current clip (createDub).

        Args:
            dub: The dub stage; omit for mode `auto`.
            lipsync: Run lip-sync after the dub.
            onscreen: Translate on-screen text last, over the lip-synced video when lip-sync is ordered.
            resume_job_id: Price resuming this failed localization job of the project (resumeJob) instead of a new
            run; the stage fields are then ignored.
            expected_cost_minutes: Accepted and ignored, so the action's body can be sent unchanged.
        """
        return self._call(
            _ops.estimateLocalization,
            _m.Estimate,
            path={"project_id": project_id},
            body={"dub": dub, "lipsync": lipsync, "onscreen": onscreen, "resume_job_id": resume_job_id, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )

    def generate_segments(
        self,
        project_id: str,
        *,
        segment_ids: Sequence[str],
        expected_cost_minutes: int,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Voice chosen segments into downloadable clips

        Voices the chosen segments (1-100) into one downloadable `SegmentClip` per segment, without rebuilding the
        video: a take stored under the job and never overwritten, at its natural duration (`fit`, `overrun_seconds`);
        any voiced clip counts as success. Text is voiced as written.

        Args:
            segment_ids: Segments of the live transcript to voice (1-100).
            expected_cost_minutes: Cap on the minutes this request may spend (any minute pool). Send the estimate's
            total_minutes. A higher current price fails with 409 cost_changed and spends...
        """
        return self._call(
            _ops.generateSegments,
            _m.Job,
            path={"project_id": project_id},
            body={"segment_ids": segment_ids, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )

    def estimate_segment_generation(
        self,
        project_id: str,
        *,
        segment_ids: Sequence[str],
        expected_cost_minutes: Optional[int] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Estimate:
        """Estimate voicing chosen segments

        Runs every check of generateSegments without writing and returns an Estimate: `segment_ids_to_voice`, speech
        seconds, price, engine, `text_adaptation` and `processing_scope`, with eligibility, reasons and
        `balance_after`. Speech is synthesized only for the chosen segments; `processing_scope.voice_setup` says
        plainly when the engine may also read other speakers' speech to prepare cloned voices (notice
        `wider_voice_setup`). That work is not charged. Without a previous dub, the notice `clips_not_reusable` says
        that the first dub voices and charges these segments again. This charge does not open the text
        (`dub_payment_required`).

        Args:
            segment_ids: Segments of the live transcript to voice (1-100).
            expected_cost_minutes: Accepted and ignored, so the action's body can be sent unchanged.
        """
        return self._call(
            _ops.estimateSegmentGeneration,
            _m.Estimate,
            path={"project_id": project_id},
            body={"segment_ids": segment_ids, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )


