class Transcript(SyncResource):
    """Transcript operations."""

    def retranslate_segments(
        self,
        project_id: str,
        *,
        segment_ids: Optional[Sequence[str]] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Retranslate segments

        Retranslates the given segments (1-1000), or every segment with source text when `segment_ids` is omitted,
        with the current instructions and glossary, in one `translation` job. Manual translations of the targeted
        segments are overwritten (restorable from versions). A segment that turns busy mid-way is skipped and
        reported.

        Args:
            segment_ids: Segments to retranslate; omit for every segment with source text. Overwrites their manual
            translations (restorable from versions).
        """
        return self._call(
            _ops.retranslateSegments,
            _m.Job,
            path={"project_id": project_id},
            body={"segment_ids": segment_ids},
            idempotency_key=idempotency_key,
            options=options,
        )

    def get_transcript(
        self,
        project_id: str,
        **options: Unpack[RequestOptions],
    ) -> _m.Transcript:
        """Get a project's transcript summary

        Returns the transcript summary: languages, segment count, speakers and counts of segments that are
        translating, voicing, failed, flagged or need a redub. Segments are listed by listSegments.
        """
        return self._call(
            _ops.getTranscript,
            _m.Transcript,
            path={"project_id": project_id},
            options=options,
        )

    def import_transcript(
        self,
        project_id: str,
        *,
        source: Optional[_p.SrtFileInputParam] = None,
        target: Optional[_p.SrtFileInputParam] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Replace the transcript from SRT subtitles

        Replaces the project's transcript with inline SRT subtitles in the project's languages (source, target or
        both; speaker labels all-or-none; equal cues and timings) and re-runs processing: source subtitles go to
        speaker detection, target-only subtitles to segment transcription. A restore point is saved and version
        history is kept. On failure the previous transcript is restored.
        """
        return self._call(
            _ops.importTranscript,
            _m.Job,
            path={"project_id": project_id},
            body={"source": source, "target": target},
            idempotency_key=idempotency_key,
            options=options,
        )

    def get_translation_settings(
        self,
        project_id: str,
        **options: Unpack[RequestOptions],
    ) -> _m.TranslationSettings:
        """Get a project's translation settings

        Returns the translation instructions and the attached glossary with its applied and latest versions
        (`outdated` when a newer glossary version exists).
        """
        return self._call(
            _ops.getTranslationSettings,
            _m.TranslationSettings,
            path={"project_id": project_id},
            options=options,
        )

    def update_translation_settings(
        self,
        project_id: str,
        *,
        translation_instructions: Optional[str] = None,
        glossary_id: Optional[str] = None,
        if_match: Optional[str] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranslationSettings:
        """Update translation instructions or glossary

        Sets or clears `translation_instructions` and `glossary_id`. Re-sending the same glossary id applies its
        latest version. It **never retranslates**: call retranslateSegments to apply the settings to existing
        segments.

        Args:
            translation_instructions: Instructions (entitlement translation_instructions); an empty string clears
            them.
            glossary_id: Glossary (entitlement glossary; matching languages); an empty string detaches. Re-sending the
            same id applies its latest version.
        """
        return self._call(
            _ops.updateTranslationSettings,
            _m.TranslationSettings,
            path={"project_id": project_id},
            body={"translation_instructions": translation_instructions, "glossary_id": glossary_id},
            if_match=if_match,
            idempotency_key=idempotency_key,
            options=options,
        )


class Segments(SyncResource):
    """Segments operations."""

    def list_segments(
        self,
        project_id: str,
        *,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        ids: Optional[Sequence[str]] = None,
        speaker_id: Optional[str] = None,
        status: Optional[Sequence[_m.SegmentStatusKnown]] = None,
        dub_state: Optional[Sequence[_m.DubStateKnown]] = None,
        needs_attention: Optional[bool] = None,
        from_seconds: Optional[float] = None,
        to_seconds: Optional[float] = None,
        q: Optional[str] = None,
        include: Optional[Sequence[_m.SegmentIncludeKnown]] = None,
        **options: Unpack[RequestOptions],
    ) -> Page[_m.Segment]:
        """List transcript segments

        Lists segments in start-time order with texts, speaker, status (`ready`, `translating`, `voicing`,
        `translation_failed`), dub state (`not_dubbed`, `current`, `outdated`), audio link and ETag. Filters: ids,
        text (`q`), speaker, status, dub state, review flag, time window; `include=words,variants` adds word timings
        and translation variants.

        Args:
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
            ids: Up to 100 segment ids.
            speaker_id: Only this speaker.
            status: Comma-separated statuses.
            dub_state: Comma-separated dub states.
            needs_attention: Only flagged (true) or unflagged (false) segments.
            from_seconds: Segments overlapping [from_seconds, to_seconds).
            to_seconds: End of the time window.
            q: Only segments whose source or translation text contains this text (1-100 characters, case-insensitive).
            include: Optional fields to fill: `words`, `variants` (comma-separated).
        """
        return self._list(
            _ops.listSegments,
            _m.SegmentList,
            path={"project_id": project_id},
            query={"limit": limit, "cursor": cursor, "ids": ids, "speaker_id": speaker_id, "status": status, "dub_state": dub_state, "needs_attention": needs_attention, "from_seconds": from_seconds, "to_seconds": to_seconds, "q": q, "include": include},
            options=options,
        )

    def create_segment(
        self,
        project_id: str,
        *,
        start_seconds: float,
        end_seconds: float,
        speaker_id: str,
        source_text: Optional[str] = None,
        translation_text: Optional[str] = None,
        needs_attention: Optional[bool] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptEditResult:
        """Insert a segment

        Inserts a segment (speaker required); works on an empty transcript. Source text without a translation starts a
        translation. An unknown speaker gets a suggested voice.

        Args:
            start_seconds: Start in seconds (<= 3 decimals).
            end_seconds: End in seconds (<= 3 decimals).
            speaker_id: Speaker (`SPEAKER_NN`).
            source_text: Source text; without a translation it is translated (<= 5000 characters; no control
            characters but newline).
            translation_text: Translation (<= 5000 characters; no control characters but newline).
            needs_attention: Review flag.
        """
        return self._call(
            _ops.createSegment,
            _m.TranscriptEditResult,
            path={"project_id": project_id},
            body={"start_seconds": start_seconds, "end_seconds": end_seconds, "speaker_id": speaker_id, "source_text": source_text, "translation_text": translation_text, "needs_attention": needs_attention},
            idempotency_key=idempotency_key,
            options=options,
        )

    def merge_segments(
        self,
        project_id: str,
        *,
        segments: Sequence[_p.SegmentRefInputParam],
        speaker_id: Optional[str] = None,
        retranslate: Optional[bool] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptEditResult:
        """Merge adjacent segments

        Merges 2-20 adjacent segments into the earliest one (server-ordered by start): texts joined with a space,
        times spanning all, variants cleared, audio dropped, the others deleted; retranslates by default.

        Args:
            segments: 2-20 adjacent segments, each with the ETag read last (no If-Match header). All ETags are checked
            in one atomic write: a stale one fails with 412 precondition...
            speaker_id: Speaker of the merged segment; default: the earliest segment's.
            retranslate: Retranslate the merged text.
        """
        return self._call(
            _ops.mergeSegments,
            _m.TranscriptEditResult,
            path={"project_id": project_id},
            body={"segments": segments, "speaker_id": speaker_id, "retranslate": retranslate},
            idempotency_key=idempotency_key,
            options=options,
        )

    def get_segment(
        self,
        project_id: str,
        segment_id: str,
        *,
        include: Optional[Sequence[_m.SegmentIncludeKnown]] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Segment:
        """Get a segment

        Returns one segment of the live transcript with its ETag.

        Args:
            include: Optional fields to fill: `words`, `variants` (comma-separated).
        """
        return self._call(
            _ops.getSegment,
            _m.Segment,
            path={"project_id": project_id, "segment_id": segment_id},
            query={"include": include},
            options=options,
        )

    def update_segment(
        self,
        project_id: str,
        segment_id: str,
        *,
        if_match: str,
        start_seconds: Optional[float] = None,
        end_seconds: Optional[float] = None,
        speaker_id: Optional[str] = None,
        source_text: Optional[str] = None,
        translation_text: Optional[str] = None,
        needs_attention: Optional[bool] = None,
        retranslate: Optional[bool] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptEditResult:
        """Update a segment

        Changes timing, speaker, source or translation text, the review flag, or retranslates. Changing the source
        without sending a translation retranslates by default. A translating segment is busy; while voicing,
        translation and speaker changes are refused.

        Args:
            start_seconds: New start in seconds (<= 3 decimals).
            end_seconds: New end in seconds (<= 3 decimals).
            speaker_id: New speaker (`SPEAKER_NN`); an unknown speaker gets a suggested voice.
            source_text: New source text (<= 5000 characters; no control characters but newline).
            translation_text: New translation (<= 5000 characters; no control characters but newline).
            needs_attention: Review flag (changing only this keeps the dub current).
            retranslate: Retranslate after the change. Default: true when source_text changes and translation_text is
            not sent.
        """
        return self._call(
            _ops.updateSegment,
            _m.TranscriptEditResult,
            path={"project_id": project_id, "segment_id": segment_id},
            body={"start_seconds": start_seconds, "end_seconds": end_seconds, "speaker_id": speaker_id, "source_text": source_text, "translation_text": translation_text, "needs_attention": needs_attention, "retranslate": retranslate},
            if_match=if_match,
            idempotency_key=idempotency_key,
            options=options,
        )

    def delete_segment(
        self,
        project_id: str,
        segment_id: str,
        *,
        if_match: str,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptEditResult:
        """Delete a segment

        Deletes a segment of the live transcript. Its translation variants come back only through
        restoreTranscriptVersion or a new retranslateSegments; createSegment cannot write variants.
        """
        return self._call(
            _ops.deleteSegment,
            _m.TranscriptEditResult,
            path={"project_id": project_id, "segment_id": segment_id},
            if_match=if_match,
            idempotency_key=idempotency_key,
            options=options,
        )

    def select_translation_variant(
        self,
        project_id: str,
        segment_id: str,
        *,
        if_match: str,
        variant_id: str,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptEditResult:
        """Select a translation variant for a segment

        Sets the segment's translation to one of its `translation_variants` (see `include=variants`) and records the
        selection; the audio is dropped.

        Args:
            variant_id: Variant id from include=variants.
        """
        return self._call(
            _ops.selectTranslationVariant,
            _m.TranscriptEditResult,
            path={"project_id": project_id, "segment_id": segment_id},
            body={"variant_id": variant_id},
            if_match=if_match,
            idempotency_key=idempotency_key,
            options=options,
        )

    def split_segment(
        self,
        project_id: str,
        segment_id: str,
        *,
        if_match: str,
        at_seconds: float,
        source: Optional[_p.SplitTextsInputParam] = None,
        translation: Optional[_p.SplitTextsInputParam] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptEditResult:
        """Split a segment in two

        Splits a segment at `at_seconds`. Without explicit texts the source splits at the word boundary nearest the
        time and missing translations are retranslated in one job. The first half keeps the id; both halves become
        `outdated`; variants are cleared and audio dropped.

        Args:
            at_seconds: Split time, strictly inside the segment; both halves >= 0.1 s, in seconds (<= 3 decimals).
        """
        return self._call(
            _ops.splitSegment,
            _m.TranscriptEditResult,
            path={"project_id": project_id, "segment_id": segment_id},
            body={"at_seconds": at_seconds, "source": source, "translation": translation},
            if_match=if_match,
            idempotency_key=idempotency_key,
            options=options,
        )


