class AsyncJobs(AsyncJobsHelpers, AsyncResource):
    """Jobs operations."""

    async def list_jobs(
        self,
        *,
        project_id: Optional[str] = None,
        media_id: Optional[str] = None,
        type: Optional[Sequence[_m.JobTypeKnown]] = None,
        status: Optional[Sequence[_m.JobStatusKnown]] = None,
        channel: Optional[_m.JobChannelKnown] = None,
        created_after: Optional[Union[str, _dt.datetime]] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> AsyncPage[_m.Job]:
        """List jobs

        Lists jobs newest first: work started through v3 (`api`, `mcp`) and automatic follow-up work on v3 projects
        (`system`). Work started in the web app or API v2 has no job: read `processing_state` or the lip-sync and
        on-screen state.

        Args:
            project_id: Only this project.
            media_id: Only this media.
            type: Comma-separated job types.
            status: Comma-separated statuses.
            channel: Only jobs started from this channel.
            created_after: Created at or after.
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
        """
        return await self._list(
            _ops.listJobs,
            _m.JobList,
            query={"project_id": project_id, "media_id": media_id, "type": type, "status": status, "channel": channel, "created_after": created_after, "limit": limit, "cursor": cursor},
            options=options,
        )

    @overload
    async def get_job(
        self,
        job_id: str,
        *,
        wait_seconds: Optional[int] = None,
        if_none_match: None = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job: ...

    @overload
    async def get_job(
        self,
        job_id: str,
        *,
        wait_seconds: Optional[int] = None,
        if_none_match: str,
        **options: Unpack[RequestOptions],
    ) -> Union[_m.Job, NotModified]: ...

    async def get_job(
        self,
        job_id: str,
        *,
        wait_seconds: Optional[int] = None,
        if_none_match: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> Union[_m.Job, NotModified]:
        """Get a job, optionally waiting for a change

        Returns a job. With `wait_seconds` (<= 20) the request returns as soon as the job changes or is terminal, or
        after the wait; with `If-None-Match` set to the previous ETag it answers 304 when nothing changed; a terminal
        job ignores `If-None-Match` and always answers 200. Non-terminal responses carry `Retry-After` (the type's
        poll hint). Status is monotonic. Finished jobs can be read for 90 days, then answer 404 `job_not_found`.

        Args:
            wait_seconds: Hold the request up to this many seconds until the job changes or is terminal (0 = return at
            once).
        """
        return await self._call(
            _ops.getJob,
            _m.Job,
            path={"job_id": job_id},
            query={"wait_seconds": wait_seconds},
            if_none_match=if_none_match,
            options=options,
        )

    async def cancel_job(
        self,
        job_id: str,
        *,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Cancel a job

        Cancels a job when its type allows it: a `media_import` while non-terminal (the media is deleted when ready)
        or an `onscreen` job while queued and not charging (refunded). Other types, `localization` included, and an
        `onscreen` job that is a stage of a `localization` run fail with `job_not_cancelable`.
        """
        return await self._call(
            _ops.cancelJob,
            _m.Job,
            path={"job_id": job_id},
            idempotency_key=idempotency_key,
            options=options,
        )

    async def resume_job(
        self,
        job_id: str,
        *,
        expected_cost_minutes: int,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Resume a failed localization job

        Continues a failed `localization` job as a new job (`parent_job_id`). Succeeded stages are never re-run or
        re-charged: the new job lists them. Failed, skipped and unreached stages start at today's price, in order,
        unless a current result reuses them at no charge. A failed job can be resumed once, and not after the project
        was deleted or a later dub cleared a succeeded lip-sync (409 `job_not_resumable`). On-screen on a lip-sync the
        plan trims answers 422.

        Args:
            expected_cost_minutes: Cap on the minutes the whole run may spend (the single total). Send the estimate's
            total_minutes. A higher current price fails with 409 cost_changed and spen...
        """
        return await self._call(
            _ops.resumeJob,
            _m.Job,
            path={"job_id": job_id},
            body={"expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )


