class AsyncLipsync(AsyncResource):
    """Lipsync operations."""

    async def get_lipsync_state(
        self,
        project_id: str,
        **options: Unpack[RequestOptions],
    ) -> _m.LipsyncState:
        """Get a project's lip-sync state

        Returns the project's lip-sync state: face check result, whether the free run is available, the latest
        lip-sync job started through v3 and the current result from any channel (with a download link unless the plan
        restricts downloads). After a later dub `outdated` is true and `current_result` is null.
        """
        return await self._call(
            _ops.getLipsyncState,
            _m.LipsyncState,
            path={"project_id": project_id},
            options=options,
        )

    async def create_lipsync(
        self,
        project_id: str,
        *,
        model: _m.LipsyncModelKnown,
        expected_cost_minutes: int,
        free_trial_run: Optional[bool] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Lip-sync a dubbed video

        Starts a `lipsync` job on the dubbed video with the `legacy` or `enhanced` model. The job charges, runs a face
        check (unless one already ran), waits for a worker and renders; the result is the lip-synced video (also
        output `lipsync_video`). No face, failures and timeouts are refunded. A later dub makes the result outdated
        (`LipsyncState.outdated`, `result.is_outdated`).

        Args:
            model: legacy or enhanced (entitlement lipsync_enhanced).
            free_trial_run: Use the one free run (1 free lip-sync minute, first 60 s); needs no previous run.
            expected_cost_minutes: Cap on the minutes this request may spend (any minute pool). Send the estimate's
            total_minutes. A higher current price fails with 409 cost_changed and spends...
        """
        return await self._call(
            _ops.createLipsync,
            _m.Job,
            path={"project_id": project_id},
            body={"model": model, "free_trial_run": free_trial_run, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )

    async def estimate_lipsync(
        self,
        project_id: str,
        *,
        model: _m.LipsyncModelKnown,
        free_trial_run: Optional[bool] = None,
        expected_cost_minutes: Optional[int] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Estimate:
        """Estimate a lip-sync run

        Runs every check of createLipsync without writing and returns an Estimate: price (minutes x model multiplier,
        or the free run), processed seconds, whether a face check is needed or already found a face, and the previous
        run's state.

        Args:
            model: legacy or enhanced (entitlement lipsync_enhanced).
            free_trial_run: Use the one free run (1 free lip-sync minute, first 60 s); needs no previous run.
            expected_cost_minutes: Accepted and ignored, so the action's body can be sent unchanged.
        """
        return await self._call(
            _ops.estimateLipsync,
            _m.Estimate,
            path={"project_id": project_id},
            body={"model": model, "free_trial_run": free_trial_run, "expected_cost_minutes": expected_cost_minutes},
            idempotency_key=idempotency_key,
            options=options,
        )


