class AsyncVersions(AsyncResource):
    """Versions operations."""

    async def list_transcript_versions(
        self,
        project_id: str,
        *,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        trigger: Optional[Sequence[_m.VersionTriggerKnown]] = None,
        **options: Unpack[RequestOptions],
    ) -> AsyncPage[_m.TranscriptVersion]:
        """List transcript versions

        Lists saved versions newest first: manual saves, web autosaves, system restore points (`restore_point`) and
        versions recorded after translations and dubs. Versions other than `manual` beyond 50 are pruned oldest first,
        never the newest `translation_completed` and `dub_completed` versions.

        Args:
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
            trigger: Comma-separated triggers.
        """
        return await self._list(
            _ops.listTranscriptVersions,
            _m.TranscriptVersionList,
            path={"project_id": project_id},
            query={"limit": limit, "cursor": cursor, "trigger": trigger},
            options=options,
        )

    async def create_transcript_version(
        self,
        project_id: str,
        *,
        label: Optional[str] = None,
        trigger: Optional[Literal["manual", "restore_point"]] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptVersion:
        """Save a transcript version

        Saves the live transcript as a version: `manual` (default; always inserts, never pruned) or `restore_point`
        (at most one per transcript per 60 s or per Idempotency-Key family; a coalesced call returns the existing
        restore point).

        Args:
            label: Version label.
            trigger: `manual` (default): always inserts and is never pruned. `restore_point`: a restore point before
            risky work; reuses the transcript's restore point from the la...
        """
        return await self._call(
            _ops.createTranscriptVersion,
            _m.TranscriptVersion,
            path={"project_id": project_id},
            body={"label": label, "trigger": trigger},
            idempotency_key=idempotency_key,
            options=options,
        )

    async def get_transcript_version(
        self,
        project_id: str,
        version_number: int,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptVersion:
        """Get a transcript version

        Returns a version with the voice assignments saved with it. Its segments are listed by
        listTranscriptVersionSegments.
        """
        return await self._call(
            _ops.getTranscriptVersion,
            _m.TranscriptVersion,
            path={"project_id": project_id, "version_number": version_number},
            options=options,
        )

    async def restore_transcript_version(
        self,
        project_id: str,
        version_number: int,
        *,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.TranscriptRestoreResult:
        """Restore a transcript version

        Replaces the live transcript with a saved version. Segment ids are re-minted: `segment_id_map` maps old to new
        ids. A restore point is saved first; voice assignments are restored when possible. Restoring the current
        version writes nothing (`already_current: true`).
        """
        return await self._call(
            _ops.restoreTranscriptVersion,
            _m.TranscriptRestoreResult,
            path={"project_id": project_id, "version_number": version_number},
            idempotency_key=idempotency_key,
            options=options,
        )

    async def list_transcript_version_segments(
        self,
        project_id: str,
        version_number: int,
        *,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        include: Optional[Sequence[_m.SegmentIncludeKnown]] = None,
        **options: Unpack[RequestOptions],
    ) -> AsyncPage[_m.TranscriptVersionSegment]:
        """List the segments of a transcript version

        Lists the segments of a saved version in time order (segment ids as they were at save time; audio links when
        the snapshot has them).

        Args:
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
            include: Optional fields to fill: `words`, `variants` (comma-separated).
        """
        return await self._list(
            _ops.listTranscriptVersionSegments,
            _m.TranscriptVersionSegmentList,
            path={"project_id": project_id, "version_number": version_number},
            query={"limit": limit, "cursor": cursor, "include": include},
            options=options,
        )


