class AsyncUploads(AsyncUploadsHelpers, AsyncResource):
    """Uploads operations."""

    async def create_upload(
        self,
        *,
        filename: str,
        content_type: _m.UploadContentTypeKnown,
        size_bytes: int,
        purpose: Optional[_m.MediaPurposeKnown] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Upload:
        """Create a presigned upload

        Creates an upload and returns one presigned PUT URL for the whole file, up to the plan's limit (at most 5 GB).
        The URL signs the exact `Content-Length` and `Content-Type`: PUT the bytes **without** an Authorization header
        and with exactly the listed headers, then call completeUpload. URLs live 1 hour; getUpload re-signs them.
        Voice samples (`purpose: voice_sample`) may be audio (<= 11 MB) or video (<= 500 MB, its audio is extracted to
        MP3 on import); larger files fail with 413 `media_too_large`.

        Args:
            filename: File name without `/`, `\\` or control characters.
            size_bytes: Exact size in bytes (<= getPlan.limits.max_upload_bytes).
            purpose: project_source (default) or voice_sample (audio <= 11 MB, or video <= 500 MB whose audio is
            extracted to MP3).
        """
        return await self._call(
            _ops.createUpload,
            _m.Upload,
            body={"filename": filename, "content_type": content_type, "size_bytes": size_bytes, "purpose": purpose},
            idempotency_key=idempotency_key,
            options=options,
        )

    async def get_upload(
        self,
        upload_id: str,
        **options: Unpack[RequestOptions],
    ) -> _m.Upload:
        """Get an upload and refresh its upload URLs

        Returns an upload, with freshly signed transfer URLs while it is pending for a key that may write
        (`media:write`; a key without it reads `transfer: null`, because the URL can overwrite the object), and its
        `media_id` and `import_job_id` once completed.
        """
        return await self._call(
            _ops.getUpload,
            _m.Upload,
            path={"upload_id": upload_id},
            options=options,
        )

    async def delete_upload(
        self,
        upload_id: str,
        **options: Unpack[RequestOptions],
    ) -> NoContent:
        """Abort a pending upload

        Aborts a pending upload and discards the bytes sent so far.
        """
        return await self._call(
            _ops.deleteUpload,
            NoContent,
            path={"upload_id": upload_id},
            options=options,
        )

    async def complete_upload(
        self,
        upload_id: str,
        *,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Complete an upload and import the media

        Checks the uploaded object, verifies its size and starts a `media_import` job that registers the file as a
        media item and whose result carries `media_id`; for a video voice sample the job extracts its audio to MP3,
        and a stored sample above 11 MB fails the job with `media_too_large`.
        """
        return await self._call(
            _ops.completeUpload,
            _m.Job,
            path={"upload_id": upload_id},
            body={},
            idempotency_key=idempotency_key,
            options=options,
        )


class AsyncUsage(AsyncResource):
    """Usage operations."""

    async def get_usage(
        self,
        *,
        group_by: Optional[Sequence[_m.UsageGroupByKnown]] = None,
        from_: Optional[Union[str, _dt.datetime]] = None,
        to: Optional[Union[str, _dt.datetime]] = None,
        period: Optional[_m.UsagePeriodKnown] = None,
        credit_type: Optional[_m.CreditTypeKnown] = None,
        feature: Optional[_m.UsageFeatureKnown] = None,
        project_id: Optional[str] = None,
        credential_id: Optional[str] = None,
        member_user_id: Optional[str] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> AsyncPage[_m.UsageBucket]:
        """Get aggregated credit usage

        Aggregates the workspace's charges and refunds into buckets grouped by up to two dimensions (`day`, `month`,
        `feature`, `project`, `token`, `member`). Refunds count in the bucket of the charge they reverse. Without
        `group_by` there is one bucket per credit type. Deleted projects are included and named. Usage across the
        payer's other workspaces is only in the web app.

        Args:
            group_by: Up to two dimensions, comma-separated (e.g. `day,feature`).
            from_: Start (inclusive, RFC 3339). Default: the payer's current billing period, else the last 30 days.
            to: End (exclusive). The span may not exceed 400 days.
            period: A billing period instead of `from`/`to`; explicit `from` or `to` replace it.
            credit_type: Only this pool.
            feature: Only this feature.
            project_id: Only this project.
            credential_id: Only this API key or OAuth grant.
            member_user_id: Only this acting member.
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
        """
        return await self._list(
            _ops.getUsage,
            _m.UsageBucketList,
            query={"group_by": group_by, "from": from_, "to": to, "period": period, "credit_type": credit_type, "feature": feature, "project_id": project_id, "credential_id": credential_id, "member_user_id": member_user_id, "limit": limit, "cursor": cursor},
            options=options,
        )

    async def list_usage_events(
        self,
        *,
        from_: Optional[Union[str, _dt.datetime]] = None,
        to: Optional[Union[str, _dt.datetime]] = None,
        period: Optional[_m.UsagePeriodKnown] = None,
        credit_type: Optional[_m.CreditTypeKnown] = None,
        feature: Optional[_m.UsageFeatureKnown] = None,
        project_id: Optional[str] = None,
        credential_id: Optional[str] = None,
        member_user_id: Optional[str] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> AsyncPage[_m.UsageEvent]:
        """List credit usage events

        Lists charges newest first, one entry per charge with its refund, attributed to a feature, project, job,
        member, key and channel where known (key, member and channel for charges of v3 jobs). Deleted projects are
        included and named. Grants and top-ups are not usage and are not listed.

        Args:
            from_: Start (inclusive, RFC 3339). Default: the payer's current billing period, else the last 30 days.
            to: End (exclusive). The span may not exceed 400 days.
            period: A billing period instead of `from`/`to`; explicit `from` or `to` replace it.
            credit_type: Only this pool.
            feature: Only this feature.
            project_id: Only this project.
            credential_id: Only this API key or OAuth grant.
            member_user_id: Only this acting member.
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
        """
        return await self._list(
            _ops.listUsageEvents,
            _m.UsageEventList,
            query={"from": from_, "to": to, "period": period, "credit_type": credit_type, "feature": feature, "project_id": project_id, "credential_id": credential_id, "member_user_id": member_user_id, "limit": limit, "cursor": cursor},
            options=options,
        )


class AsyncVoiceClones(AsyncResource):
    """VoiceClones operations."""

    async def list_voice_clones(
        self,
        *,
        name_contains: Optional[str] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> AsyncPage[_m.VoiceClone]:
        """List voice clones

        Lists the workspace's reusable voice clones newest first (temporary instant clones are not listed).

        Args:
            name_contains: Only clones whose name contains this text (1-100 characters, case-insensitive).
            limit: Page size.
            cursor: Opaque cursor from `next_cursor`; keep the same filters on every page.
        """
        return await self._list(
            _ops.listVoiceClones,
            _m.VoiceCloneList,
            query={"name_contains": name_contains, "limit": limit, "cursor": cursor},
            options=options,
        )

    async def create_voice_clone(
        self,
        *,
        name: str,
        source: _p.VoiceCloneSourceInputParam,
        rights_confirmed: Literal[True],
        settings: Optional[_p.VoiceCloneSettingsInputParam] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.Job:
        """Create a voice clone

        Creates a reusable workspace voice clone from 1-10 voice samples (media imported with purpose `voice_sample`:
        audio, or video whose audio was extracted to MP3; each <= 11 MB as stored) or from one speaker of a project,
        and starts a `voice_clone` job. The clone exists at once with `status: processing`. Send `rights_confirmed:
        true` to attest that you may clone the voice.

        Args:
            name: Clone name.
            rights_confirmed: Attestation that you have the right to clone this voice (you are the speaker or have
            their permission). Must be true; recorded in the audit log with the cred...
        """
        return await self._call(
            _ops.createVoiceClone,
            _m.Job,
            body={"name": name, "source": source, "settings": settings, "rights_confirmed": rights_confirmed},
            idempotency_key=idempotency_key,
            options=options,
        )

    async def get_voice_clone_quota(
        self,
        **options: Unpack[RequestOptions],
    ) -> _m.VoiceCloneQuota:
        """Get the voice clone quota

        Returns the workspace's clone limit, clones counted against it (processing and ready) and what remains.
        """
        return await self._call(
            _ops.getVoiceCloneQuota,
            _m.VoiceCloneQuota,
            options=options,
        )

    async def get_voice_clone(
        self,
        voice_clone_id: str,
        **options: Unpack[RequestOptions],
    ) -> _m.VoiceClone:
        """Get a voice clone

        Returns a voice clone with its status, settings and per-language samples.
        """
        return await self._call(
            _ops.getVoiceClone,
            _m.VoiceClone,
            path={"voice_clone_id": voice_clone_id},
            options=options,
        )

    async def update_voice_clone(
        self,
        voice_clone_id: str,
        *,
        name: Optional[str] = None,
        settings: Optional[_p.VoiceCloneSettingsInputParam] = None,
        idempotency_key: Optional[str] = None,
        **options: Unpack[RequestOptions],
    ) -> _m.VoiceClone:
        """Rename a voice clone or change its settings

        Renames a clone or changes its settings (accent, expressiveness). Settings apply to the next segment
        generation or dub at once; each language's sample is regenerated when the clone is next used in that language,
        never on a read (`samples_status: regenerating`, that language's `sample: null` until then). Source files
        cannot be replaced.

        Args:
            name: Clone name.
        """
        return await self._call(
            _ops.updateVoiceClone,
            _m.VoiceClone,
            path={"voice_clone_id": voice_clone_id},
            body={"name": name, "settings": settings},
            idempotency_key=idempotency_key,
            options=options,
        )

    async def delete_voice_clone(
        self,
        voice_clone_id: str,
        **options: Unpack[RequestOptions],
    ) -> NoContent:
        """Delete a voice clone

        Deletes a clone. Speakers that used it in any project of the workspace are reassigned (their projects become
        `voice_edited`) and the provider voice is deleted.
        """
        return await self._call(
            _ops.deleteVoiceClone,
            NoContent,
            path={"voice_clone_id": voice_clone_id},
            options=options,
        )


class AsyncResources:
    """The client attributes, one per resource."""

    account: AsyncAccount
    projects: AsyncProjects
    glossaries: AsyncGlossaries
    jobs: AsyncJobs
    catalogs: AsyncCatalogs
    media: AsyncMedia
    dubbing: AsyncDubbing
    exports: AsyncExports
    lipsync: AsyncLipsync
    onscreen: AsyncOnscreen
    transcript: AsyncTranscript
    segments: AsyncSegments
    speakers: AsyncSpeakers
    versions: AsyncVersions
    voices: AsyncVoices
    uploads: AsyncUploads
    usage: AsyncUsage
    voice_clones: AsyncVoiceClones

    def _init_resources(self) -> None:
        self.account = AsyncAccount(self)
        self.projects = AsyncProjects(self)
        self.glossaries = AsyncGlossaries(self)
        self.jobs = AsyncJobs(self)
        self.catalogs = AsyncCatalogs(self)
        self.media = AsyncMedia(self)
        self.dubbing = AsyncDubbing(self)
        self.exports = AsyncExports(self)
        self.lipsync = AsyncLipsync(self)
        self.onscreen = AsyncOnscreen(self)
        self.transcript = AsyncTranscript(self)
        self.segments = AsyncSegments(self)
        self.speakers = AsyncSpeakers(self)
        self.versions = AsyncVersions(self)
        self.voices = AsyncVoices(self)
        self.uploads = AsyncUploads(self)
        self.usage = AsyncUsage(self)
        self.voice_clones = AsyncVoiceClones(self)


__all__ = ["AsyncResources", "SyncResources"]
